const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.spark}"/></svg>`;
function numeric(value,min=-1000000,max=1000000){if(typeof value==='boolean')throw Error('Bool ist keine Zahl.');const n=Number(value);if(!Number.isFinite(n)||n<min||n>max)throw Error(`Zahl muss zwischen ${min} und ${max} liegen.`);return n;}
const KEYS=new Set([... 'ABCDEFGHIJKLMNOPQRSTUVWXYZ','SPACEBAR','ENTER','ESC','PAGE_UP','PAGE_DOWN','UP_ARROW','DOWN_ARROW','LEFT_ARROW','RIGHT_ARROW','TAB']);
function parseFlat(source){if(typeof source!=='string'||source.length>65536)throw Error('Skript zu lang (max. 16 KB).');const steps=[];source.split(/\r?\n/).forEach((raw,i)=>{const l=raw.trim();if(!l||l.startsWith('#'))return;if(steps.length>=200)throw Error('Maximal 200 Schritte.');let m=l.match(/^sleep\s+([\d.]+)$/);if(m){steps.push({op:'sleep',seconds:numeric(m[1],0,60),line:i+1});return;}m=l.match(/^(mass|p[1-9]\d*)\s+(.+)$/);if(!m)throw Error(`Zeile ${i+1}: Ziel mass oder p1/p2/… fehlt; Blocks/Loops werden noch nicht unterstützt.`);const item={target:m[1],line:i+1},body=m[2];if(m=body.match(/^sendkey\s+(\w+)(?:\s*,?\s+([\d.]+))?$/)){if(!KEYS.has(m[1]))throw Error('Nicht unterstützte Taste.');Object.assign(item,{op:'key',key:m[1],seconds:numeric(m[2]||.1,.01,5)});}else if(m=body.match(/^tp\s+XYZ\(\s*([^,]+),\s*([^,]+),\s*([^\)]+)\)$/)){Object.assign(item,{op:'teleport',xyz:m.slice(1).map(v=>numeric(v))}); }else if(body==='tp quest'){Object.assign(item,{op:'quest_tp'});}else if(body==='tp navquest'){Object.assign(item,{op:'navmap_tp',timeout:20});}else if(body==='freecam'){Object.assign(item,{op:'freecam'});}else if(body==='tp camera'){Object.assign(item,{op:'camera_tp'});}else if(body==='pass'){Object.assign(item,{op:'pass'});}else if(body==='waitforloading completion'){Object.assign(item,{op:'wait_loading',timeout:120});}else if(m=body.match(/^waitforwindow\s+"([^"\n]+)"\s+(\d+)$/)){if(m[1].length>180||!m[1].trim())throw Error('Name ungültig.');Object.assign(item,{op:'wait_window',name:m[1].trim(),timeout:numeric(m[2],1,120)});}else if(m=body.match(/^tp nearest\s+"([^"\n]+)"$/)){if(m[1].length>180||!m[1].trim())throw Error('Name ungültig.');Object.assign(item,{op:'nearest_entity',query:m[1].trim()});}else if(m=body.match(/^cast\s+"([^"\n]+)"\s+@(self|enemy|none)$/)){if(m[1].length>180||!m[1].trim())throw Error('Name ungültig.');Object.assign(item,{op:'cast',name:m[1].trim(),card_target:m[2]});}else if(m=body.match(/^(entitytp|clickwindow)\s+"([^"\n]+)"$/)){if(m[2].length>180||!m[2].trim())throw Error('Name ungültig.');Object.assign(item,{op:m[1]==='entitytp'?'entity_tp':'click_window',name:m[2]});}else if(m=body.match(/^speed\s+(\d+)$/)){Object.assign(item,{op:'speed',percent:numeric(m[1],0,300)});}else if(body==='restorespeed'){Object.assign(item,{op:'restore_speed'});}else if(body==='waitforcombat completion'){Object.assign(item,{op:'wait_combat',timeout:300});}else throw Error(`Zeile ${i+1}: Befehl nicht unterstützt.`);steps.push(item);});if(!steps.length)throw Error('Das Skript enthält keine Schritte.');return steps;}
function parseScript(source){if(typeof source!=='string'||source.length>65536)throw Error('Skript zu lang (max. 16 KB).');const stack=[{steps:[],count:1}];source.split(/\r?\n/).forEach((raw,i)=>{const line=raw.trim();if(!line||line.startsWith('#'))return;const m=line.match(/^times\s+(\d+)\s*\{$/);if(m){if(stack.length>=4)throw Error('Maximal drei verschachtelte Wiederholungen.');stack.push({steps:[],count:numeric(m[1],1,50)});return;}if(line==='}'){if(stack.length===1)throw Error('Unerwartete schließende Klammer.');const frame=stack.pop();if(!frame.steps.length)throw Error('Leere Wiederholung.');const expanded=Array.from({length:frame.count},()=>frame.steps).flat();if(stack.at(-1).steps.length+expanded.length>200)throw Error('Maximal 200 Schritte inklusive Wiederholungen.');stack.at(-1).steps.push(...expanded);return;}const item=parseFlat(line)[0];item.line=i+1;stack.at(-1).steps.push(item);if(stack.at(-1).steps.length>200)throw Error('Maximal 200 Schritte.');});if(stack.length!==1)throw Error('Wiederholung nicht geschlossen.');if(!stack[0].steps.length)throw Error('Das Skript enthält keine Schritte.');return stack[0].steps;}
const SCRIPT_TEMPLATES=[{"id": "after-combat", "name": "Nach dem Kampf", "source": "mass waitforcombat completion\nsleep 0.5\nmass sendkey W 0.2\nsleep 3\n"}, {"id": "interact-repeat", "name": "X wiederholen", "source": "times 3 {\n  mass sendkey X 0.1\n  sleep 0.5\n}\n"}, {"id": "navquest", "name": "Navmap zum Quest-Ziel", "source": "mass tp navquest\nsleep 1\nmass sendkey X 0.1\n"}, {"id": "quest-direct", "name": "Direkt zum Quest-Ziel", "source": "mass tp quest\nsleep 0.5\nmass sendkey X 0.1\n"}, {"id": "window", "name": "Auf Interaktion warten", "source": "mass waitforwindow \"NPCRangeWin\" 30\nmass sendkey X 0.1\n"}, {"id": "loading", "name": "Nach dem Laden fortfahren", "source": "mass waitforloading completion\nsleep 1\nmass sendkey W 0.2\n"}, {"id": "entity", "name": "Entity ansteuern", "source": "# Namen vor dem Start im Inspector prüfen\np1 entitytp \"Estate_Clue\"\nsleep 0.5\np1 sendkey X 0.1\n"}, {"id": "nearest", "name": "Nächste Truhe", "source": "# Suchbegriff vor dem Start prüfen\np1 tp nearest \"Chest\"\nsleep 0.5\np1 sendkey X 0.1\n"}, {"id": "speed", "name": "Geschwindigkeit zeitweise ändern", "source": "mass speed 100\nmass sendkey W 0.5\nsleep 1\nmass restorespeed\n"}, {"id": "freecam", "name": "Freecam einschalten", "source": "p1 freecam\n"}, {"id": "camera", "name": "Zum Freecam-Standort", "source": "# Freecam vorher aktivieren\np1 tp camera\n"}, {"id": "combat", "name": "Karte auf dich selbst", "source": "# Nur in der Planungsphase; Namen aus Combat übernehmen\np1 cast \"LifeBlade\" @self\n"}, {"id": "pass", "name": "Kampfrunde passen", "source": "# Nur in der Planungsphase\nmass pass\n"}];
