 trace('app.init.begin');
 const handoff=new URLSearchParams(location.hash.slice(1));const launchToken=handoff.get('pair')||sessionPair.get();diag.secret(launchToken);trace('pairing.handoff',{present:Boolean(launchToken)});if(launchToken)history.replaceState(null,'',location.pathname+location.search+'#overview');
 const $=id=>document.getElementById(id),all=selector=>[...document.querySelectorAll(selector)];
 const state={connected:false,demo:false,bridgeDemo:false,dialogue:false,automations:{combat:false,dialogue:false,questing:false,sigil:false},clients:[],selected:new Set(),logs:[],running:false,inspector:'entities',inspectData:null,socket:null,pending:new Map(),busy:false,scripts:[],waypoints:[]};
 let seq=0,toastTimer,runner=null,settings=null,tools=null,studio=null,fishing=null,raids=null,uiPrefs={...MW_UI_DEFAULTS};
 const defaults=[{id:'after-combat',name:'Nach dem Kampf',source:'# Nach einem bereits laufenden Kampf\n# p1/p2 folgen der Reihenfolge der ausgewählten Clients\nmass waitforcombat completion\nsleep 0.5\nmass sendkey W 0.2\nsleep 3\n'},{id:'interact',name:'Interagieren',source:'# X an alle ausgewählten Clients\nmass sendkey X 0.1\nsleep 0.5\n'},{id:'coordinates',name:'Koordinaten-Beispiel',source:'# Nur Beispielwerte — vor der Ausführung anpassen!\np1 tp XYZ(100, 200, 0)\nsleep 0.5\n'}];
 function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
 state.scripts=readStore('mythic-scripts-v1',defaults).filter(s=>s&&typeof s.id==='string'&&typeof s.name==='string'&&typeof s.source==='string');
