 function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{toast('Browser-Speicher ist nicht verfügbar. Exportiere deine Daten.');}}
 function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
 function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon));el.removeAttribute('data-icon');});}
 function log(message,level='info'){state.logs.push({time:new Date().toLocaleTimeString('de-DE'),message:String(message),level,mode:state.demo||state.bridgeDemo?'demo':'live'});if(state.logs.length>uiPrefs.log_limit)state.logs.splice(0,state.logs.length-uiPrefs.log_limit);renderLogs();}
 function renderLogs(){$('log-list').innerHTML=state.logs.map(l=>`<div class="log-row ${esc(l.level)}"><span class="log-time">${esc(l.time)}</span><span class="log-message">${esc(l.message)}</span></div>`).join('');$('log-count').textContent=`${state.logs.length} Einträge`;$('log-list').scrollTop=$('log-list').scrollHeight;}
 function navigate(page){if(page==='modules')page='setup';if(page==='inspector')page='tools';if(settings)settings.leave();if(!['overview','hooking','scripts','combat','setup','settings','tools','fishing','raid'].includes(page))page='overview';all('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+page));all('.nav').forEach(el=>el.classList.toggle('active',el.dataset.page===page));$('breadcrumb').textContent={overview:'Übersicht',hooking:'Hooking',scripts:'Skripte / Bot',combat:'Combat',setup:'Bridge einrichten',settings:'Einstellungen',tools:'Tools',fishing:'Angeln',raid:'Raid'}[page];if(location.hash!==`#${page}`)history.replaceState(null,'',`#${page}`);window.scrollTo({top:0,behavior:'instant'});}
 all('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.page));window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));all('[data-connect]').forEach(b=>b.onclick=()=>{navigate('setup');$('bridge-token').focus();});$('settings-button').onclick=()=>navigate('settings');$('hero-setup').onclick=()=>navigate('setup');
 const ids=()=>state.clients.filter(c=>state.selected.has(c.id)).map(c=>c.id);
