 $('diagnostic-check').onclick=async()=>{trace('health.check.begin');$('diagnostic-status').textContent='Lokale Bridge wird geprüft …';const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch('https://localhost:18761/health',{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('HTTP '+response.status);const data=await response.json();trace('health.check.ready',data);$('diagnostic-status').textContent=`Bridge erreichbar · ${data.release||data.version} · ${data.connected?'bereits mit einem Dashboard verbunden':'noch nicht gekoppelt'}`;}catch(e){trace('health.check.failed',{message:e.message});$('diagnostic-status').textContent='Bridge nicht erreichbar: EXE, Zertifikat und lokalen Netzwerkzugriff prüfen. Diagnose herunterladen.';}finally{clearTimeout(timer);}};

 async function command(op,args={}){if(state.demo)return demoCommand(op,args);if(!state.connected||!state.socket||state.socket.readyState!==1){trace('command.blocked',{op,connected:state.connected,readyState:state.socket?.readyState});throw Error('Zuerst die lokale Bridge verbinden.');}const id=String(++seq);trace('command.sent',{op,id});return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{state.pending.delete(id);trace('command.timeout',{op,id});reject(Error('Zeitlimit erreicht. Bridge-Protokoll prüfen; den Befehl nicht blind wiederholen.'));},60000);state.pending.set(id,{resolve,reject,timer});state.socket.send(JSON.stringify({id,op,args}));});}
 async function action(op,args){if(state.busy){toast('Ein Befehl läuft bereits.');return;}state.busy=true;render();try{const data=await command(op,args);if(op==='hook'&&Array.isArray(data)&&data.some(d=>!d.ok)){log('Mindestens ein Hook fehlgeschlagen. Details an der Client-Karte.','error');toast('Hook teilweise fehlgeschlagen. Client-Fehler prüfen.');}else{log(`${state.demo?'DEMO · ':''}${{scan:'Clients gesucht',hook:'Hooks aktiviert',unhook:'Hooks entfernt',teleport:'XYZ-Teleport gesendet',key:'Taste gesendet',sync:'Position synchronisiert',quest_tp:'Quest-Teleport gesendet',quest_position:'Quest-Ziel gelesen',nearest_entity:'Entity angesteuert',speed:'Geschwindigkeit gesetzt',restore_speed:'Geschwindigkeit wiederhergestellt',camera_tp:'Zur Freecam teleportiert',rename:'Fenstertitel geändert',stats:'Statistiken gelesen',dialogue:'Dialog-Automatik umgeschaltet',stop:'Automatik gestoppt',freecam:'Kamera umgeschaltet',entity_tp:'Entity-Teleport gesendet',click_window:'Fensterklick gesendet',cast:'Kartenaktion gesendet',pass:'Pass-Befehl gesendet'}[op]||op}.`);if(uiPrefs.notifications)toast(state.demo?'Demo-Aktion ausgeführt.':'Befehl verarbeitet.');}return data;}catch(e){log(e.message,'error');toast(e.message);}finally{state.busy=false;render();}}
 const safe=fn=>async()=>{try{await fn();}catch(e){toast(e.message);log(e.message,'error');}};
 $('scan-button').onclick=()=>action('scan');$('select-all').onclick=()=>{if(ids().length===state.clients.length)state.selected.clear();else state.selected=new Set(state.clients.map(c=>c.id));render();};$('hook-button').onclick=safe(()=>action('hook',{ids:requireIds()}));$('unhook-button').onclick=safe(()=>action('unhook',{ids:requireIds()}));
