 $('open-teleport').onclick=()=>{$('teleport-dialog').showModal();renderWaypoints();};$('open-keys').onclick=()=>$('keys-dialog').showModal();all('.close-modal').forEach(b=>b.onclick=()=>b.closest('dialog').close());all('dialog').forEach(d=>d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));
