 $('save-waypoint').onclick=safe(()=>{const name=$('waypoint-name').value.trim();if(!name)throw Error('Wegpunktname eingeben.');const coords=['tp-x','tp-y','tp-z'].map(id=>numeric($(id).value));const c=state.clients.find(c=>c.id===ids()[0]);state.waypoints.push({name,xyz:coords,zone:c?.zone??null});persist('mythic-waypoints-v1',state.waypoints);renderWaypoints();toast('Wegpunkt in diesem Browser gespeichert.');});
 function renderWaypoints(){$('waypoint-list').innerHTML=state.waypoints.map((w,i)=>`<div class="waypoint-item"><button data-waypoint="${i}">${esc(w.name)}<small>${esc(w.xyz.join(' / '))} · ${esc(w.zone||'Zone unbekannt')}</small></button><button class="icon-button" data-remove-waypoint="${i}" aria-label="Wegpunkt löschen">${icon('trash')}</button></div>`).join('');all('[data-waypoint]').forEach(b=>b.onclick=safe(()=>{const w=state.waypoints[Number(b.dataset.waypoint)];const selected=state.clients.filter(c=>state.selected.has(c.id));if(w.zone&&selected.some(c=>c.zone!==w.zone))throw Error('Wegpunkt liegt in einer anderen oder unbekannten Zone.');['tp-x','tp-y','tp-z'].forEach((id,i)=>$(id).value=w.xyz[i]);toast('Koordinaten geladen. Mit Teleportieren ausführen.');}));all('[data-remove-waypoint]').forEach(b=>b.onclick=()=>{state.waypoints.splice(Number(b.dataset.removeWaypoint),1);persist('mythic-waypoints-v1',state.waypoints);renderWaypoints();});}
 function download(filename,data,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
