 const defaultBlocks=MW_DEFAULT_LIBRARY;
 let customBlocks=readStore('mythic-blocks-v1',[]).filter(b=>b&&typeof b.name==='string'&&typeof b.source==='string'&&typeof b.description==='string').slice(0,90),catalog=[];
 const customMap=()=>Object.fromEntries(customBlocks.map(b=>[b.name,b.source]));
 const libraryMap=()=>({...Object.fromEntries(defaultBlocks.map(b=>[b.name,b.source])),...customMap()});
 async function syncBlocks(){await command('set_block_library',{blocks:customMap()});$('block-status').textContent='Bibliothek in der Bridge gespeichert · auch für Spiel-Shortcuts verfügbar.';}
 function storeBlocks(next,nativeValidated=false){const map=Object.fromEntries(next.map(b=>[b.name,b.source]));if(next.length>90||new Set(next.map(b=>b.name)).size!==next.length)throw Error('Maximal 90 eindeutige eigene Blöcke.');if(JSON.stringify(map).length>262144)throw Error('Bibliothek zu groß (max. 256 KB).');if(!nativeValidated)compileBot('sleep 0',{...Object.fromEntries(defaultBlocks.map(b=>[b.name,b.source])),...map},parseFlat);customBlocks=next;persist('mythic-blocks-v1',next);renderBlocks();renderCatalog();$('block-status').textContent='Im Browser gespeichert. Vor Start und Prüfung wird die Bibliothek in die Bridge übertragen.';}
 async function checkedStoreBlocks(next){try{storeBlocks(next);}catch(error){if(!state.connected)throw Error('Bibliothek braucht die Deimos-Prüfung in der Bridge: '+error.message);await command('validate_block_library',{blocks:Object.fromEntries(next.map(b=>[b.name,b.source]))});storeBlocks(next,true);}}
 function renderBlocks(){const merged=new Map(defaultBlocks.map(b=>[b.name,{...b,default:true}]));customBlocks.forEach(b=>merged.set(b.name,{...b,default:false}));const rows=[...merged.values()].filter(b=>(b.name+' '+b.description).toLowerCase().includes($('block-search').value.toLowerCase()));$('block-list').innerHTML=rows.map(b=>`<div class="block-item"><code>call ${esc(b.name)}</code><p>${esc(b.description)} · ${b.default?'Standard':'Eigener Block'}</p><div class="actions"><button class="button compact" data-block-insert="${esc(b.name)}">Call einfügen</button><button class="button compact" data-block-edit="${esc(b.name)}">Bearbeiten</button></div></div>`).join('');all('[data-block-insert]').forEach(b=>b.onclick=()=>{const el=$('script-editor'),call='call '+b.dataset.blockInsert+'\n',start=el.selectionStart??el.value.length,end=el.selectionEnd??start;el.value=el.value.slice(0,start)+call+el.value.slice(end);el.focus();});all('[data-block-edit]').forEach(b=>b.onclick=()=>{const entry=merged.get(b.dataset.blockEdit);$('block-name').value=entry.name;$('block-description').value=entry.description;$('block-source').value=entry.source;});}
 $('block-search').oninput=renderBlocks;
 $('new-block').onclick=()=>{['block-name','block-description','block-source'].forEach(id=>$(id).value='');$('block-name').focus();};
 $('save-block').onclick=safe(async()=>{const name=$('block-name').value.trim(),description=$('block-description').value.trim(),source=$('block-source').value;if(!source.trim())throw Error('Blockinhalt eingeben.');const next=[...customBlocks.filter(b=>b.name!==name),{name,description,source}];if(studio.engine()==='deimos'){if(!state.connected)throw Error('Expertmode-Blöcke benötigen die Bridge zur Prüfung.');await command('validate_block_library',{blocks:Object.fromEntries(next.map(b=>[b.name,b.source]))});storeBlocks(next,true);}else storeBlocks(next);toast('Bibliotheksblock gespeichert.');});
 $('delete-block').onclick=safe(async()=>{const name=$('block-name').value.trim();if(!customBlocks.some(b=>b.name===name))throw Error('Standardblöcke bleiben verfügbar. Eigene Überschreibungen kannst du entfernen.');await checkedStoreBlocks(customBlocks.filter(b=>b.name!==name));$('new-block').click();toast('Eigener Block entfernt; Standarddefinition gilt wieder.');});
