 $('import-blocks').onchange=safe(async()=>{const file=$('import-blocks').files[0];if(!file)return;if(file.size>300000)throw Error('Importdatei zu groß.');const value=JSON.parse(await file.text());if(value.version!==1||!Array.isArray(value.blocks)||value.blocks.some(b=>!b||typeof b.name!=='string'||typeof b.description!=='string'||b.description.length>180||typeof b.source!=='string'))throw Error('Ungültige Blockdatei.');const map=new Map(customBlocks.map(b=>[b.name,b]));value.blocks.forEach(b=>map.set(b.name,b));await checkedStoreBlocks([...map.values()]);$('import-blocks').value='';toast('Bibliotheksblöcke importiert.');});
