 $('delete-script').onclick=safe(()=>{if(!currentScript)throw Error('Gespeicherten Bot auswählen.');state.scripts=state.scripts.filter(s=>s.id!==currentScript);persist('mythic-scripts-v1',state.scripts);currentScript=null;$('script-name').value='Neuer Bot';$('script-editor').value='# Dein Bot\n';renderScripts();});
 const botChecks=new Map();
 function botCompatibility(bot){const checked=botChecks.get(bot.source);if(checked)return checked;return {ok:true,message:'Deimos Expertmode · Bridge-Prüfung vor Start'};}
 async function checkCatalog(){if(!state.connected)return;for(const bot of catalog){try{const result=await command('validate_script',{source:bot.source,engine:'deimos'});botChecks.set(bot.source,{ok:true,message:`Deimos geprüft · ${result.steps} Anweisungen`});}catch(e){botChecks.set(bot.source,{ok:false,message:e.message});}}renderCatalog();}

 function renderCatalog(){const q=$('bot-search').value.toLowerCase(),rows=catalog.filter(b=>(b.name+' '+b.world+' '+b.author).toLowerCase().includes(q));$('bot-catalog').innerHTML='<div class="catalog-grid">'+rows.map(b=>{const c=botCompatibility(b);return `<article class="catalog-item"><h3>${esc(b.name)}</h3><small>${esc(b.world)} · ${esc(b.author)}<br>Clients ${esc(b.clients)} · ${esc(b.zone)}</small><p class="compatibility ${c.ok?'ready':'unsupported'}">${esc(c.message)}</p><div class="actions"><button class="button compact" data-bot-load="${esc(b.path)}">In Editor laden</button><button class="button primary compact" data-bot-run="${esc(b.path)}" ${c.ok?'':'disabled'}>Starten</button><a class="button compact" href="${esc(b.url)}" target="_blank" rel="noopener">Quelle ↗</a></div></article>`;}).join('')+'</div>';function loadBot(path){const b=catalog.find(b=>b.path===path);currentScript=null;$('script-name').value=b.name.slice(0,80);$('script-editor').value=b.source;$('script-engine').value='deimos';if(studio)studio.update();$('script-validation').textContent=botCompatibility(b).message;renderScripts();navigate('scripts');return b;}all('[data-bot-load]').forEach(b=>b.onclick=()=>loadBot(b.dataset.botLoad));all('[data-bot-run]').forEach(b=>b.onclick=safe(()=>{const bot=loadBot(b.dataset.botRun),count=ids().length,match=bot.clients?.match(/^(==|<=|>=|<|>)\s*(\d+)$/);if(match){const n=Number(match[2]),ok={'==':count===n,'<=':count<=n,'>=':count>=n,'<':count<n,'>':count>n}[match[1]];if(!ok)throw Error('Dieser Bot benötigt Clients '+bot.clients+'.');}const zones=state.clients.filter(c=>state.selected.has(c.id)&&c.hooked).map(c=>c.zone);if(bot.zone&&bot.zone!=='*'&&zones.some(z=>z!==bot.zone))throw Error('Startzone prüfen: '+bot.zone+'. Originalquelle und Bot-Kommentare beachten.');$('run-script').click();}));const active=catalog.filter(b=>botCompatibility(b).ok).length;$('bot-catalog-status').textContent=`${rows.length} / ${catalog.length} Bots · ${active} aktiv · ${catalog.length-active} benötigen Anpassungen · Expertmode wird in der Bridge geprüft · GPL-3.0 · Snapshot ${catalog[0]?.revision?.slice(0,12)||''}`;}
 $('bot-search').oninput=renderCatalog;
 $('refresh-bots').onclick=safe(async()=>{$('refresh-bots').disabled=true;try{const data=await fetchForkCatalog();catalog=data;botChecks.clear();persist('mythic-fork-catalog-v1',data);renderCatalog();checkCatalog();toast('Bot-Bibliothek aus deinem Fork aktualisiert.');}finally{$('refresh-bots').disabled=false;}});
 fetch('upstream-bots.json').then(r=>r.json()).then(data=>{catalog=readStore('mythic-fork-catalog-v1',data);if(!Array.isArray(catalog)||catalog.some(b=>!b||typeof b.source!=='string'||typeof b.name!=='string'||typeof b.path!=='string'||typeof b.url!=='string'||!b.url.startsWith('https://github.com/xLordTime/bots/')))catalog=data;renderCatalog();checkCatalog();}).catch(()=>$('bot-catalog-status').textContent='Bot-Bibliothek konnte nicht geladen werden.');
