 function enterDemo(){if(state.connected||state.socket){toast('Zuerst die Bridge-Verbindung trennen.');return;}state.demo=true;state.clients=[{id:'demo1',pid:10001,title:'Oliver · Life',zone:'WizardCity/Commons',position:[125,840,12],health:10420,mana:235,level:170,battle:false,hooked:false},{id:'demo2',pid:10002,title:'Explorer · Storm',zone:'WizardCity/Commons',position:[185,910,12],health:8120,mana:220,level:170,battle:false,hooked:false},{id:'demo3',pid:10003,title:'Mythic · Death',zone:'WizardCity/Commons',position:[250,985,12],health:9830,mana:250,level:170,battle:false,hooked:false}];state.selected=new Set(['demo1']);log('DEMO gestartet. Keine Verbindung zum Spiel; alle Aktionen sind Simulationen.','warning');render();}
 function exitDemo(){if(runner)runner.abort();runner=null;state.demo=false;state.running=false;state.clients=[];state.selected.clear();log('Demo beendet.');render();}
 $('demo-button').onclick=enterDemo;$('exit-demo').onclick=()=>state.demo?exitDemo():disconnect();
 function demoSelected(selected,hooked=true){if(!Array.isArray(selected)||!selected.length)throw Error('Clients auswählen.');const rows=selected.map(id=>state.clients.find(c=>c.id===id));if(rows.some(c=>!c)||hooked&&rows.some(c=>!c.hooked))throw Error('Clients zuerst hooken (Demo).');return rows;}
 async function demoCommand(op,args){if(op==='movement'){const config=settings.value().movement,hooked=state.clients.filter(c=>c.hooked).map(c=>c.id),scope=config.scope==='all'?hooked:ids();demoSelected(scope);const source=args.source||$('movement-leader').value||ids().find(i=>hooked.includes(i))||scope[0];if(args.action.endsWith('_toggle')&&args.action!=='speed_toggle'){const mode=args.action.split('_')[0];state.automations[mode]=!state.automations[mode];if(mode==='questing'&&state.automations[mode])state.automations.sigil=false;if(mode==='sigil'&&state.automations[mode])state.automations.questing=false;state.dialogue=state.automations.dialogue;render();return {automations:state.automations};}if(args.action==='interact')return demoCommand('key',{ids:scope,key:'X',seconds:settings.keySeconds()});if(args.action==='sync')return demoCommand('sync',{ids:scope.filter(i=>i!==source),source});if(['quest_tp','quest_all'].includes(args.action))return demoCommand('quest_tp',{ids:args.action==='quest_tp'?[source]:scope});if(args.action==='speed_toggle'){state.demoSpeed=!state.demoSpeed;render();return{speed:state.demoSpeed};}return demoCommand(args.action,{ids:config.freecam_scope==='selected'?ids():[source]});}if(op==='dialogue'){if(args.enabled)demoSelected(args.ids);state.dialogue=args.enabled;state.automations.dialogue=args.enabled;render();return{dialogue:state.dialogue};}if(op==='scan')return state.clients;if(op==='stop'){state.dialogue=false;state.automations={combat:false,dialogue:false,questing:false,sigil:false};if(runner)runner.abort();state.running=false;render();return{stopped:true};}if(op==='validate_script')return{steps:compileBot(args.source,libraryMap(),parseFlat).instructions};if(state.running&&!['entities','cards','ui_tree'].includes(op))throw Error('Skript zuerst stoppen.');const clients=demoSelected(args.ids,!['hook','unhook'].includes(op));if(op==='hook'||op==='unhook'){clients.forEach(c=>c.hooked=op==='hook');render();return op==='hook'?clients.map(c=>({pid:c.id,ok:true})):{unhooked:args.ids};}if(op==='quest_position'||op==='quest_tp'){if(op==='quest_tp')clients.forEach(c=>c.position=[500,800,12]);return clients.map(c=>({id:c.id,zone:c.zone,position:[500,800,12]}));}if(op==='stats')return clients.map(c=>({id:c.id,title:c.title,stats:{current_hitpoints:c.health,current_mana:c.mana,current_gold:10000,reference_level:c.level}}));if(op==='rename')clients.forEach(c=>c.title=args.title);else if(op==='nearest_entity'||op==='camera_tp')clients.forEach(c=>c.position=[600,980,12]);else if(op==='speed')numeric(args.percent,0,300);else if(op==='restore_speed'){}else if(op==='teleport')clients.forEach(c=>c.position=args.xyz.map(v=>numeric(v)));else if(op==='sync'){const s=demoSelected([args.source])[0];clients.forEach(c=>c.position=[...s.position]);}else if(op==='key'){if(!KEYS.has(args.key))throw Error('Ungültige Taste.');numeric(args.seconds,.01,5);if(args.key==='W')clients.forEach(c=>c.position[1]+=args.seconds*580);}else if(op==='entities')return[{id:clients[0].id,entities:[{name:'Demo_Chest_001',display:'Demo-Truhe',position:[600,980,12]},{name:'Demo_NPC_001',display:'Demo-Zauberer',position:[220,500,12]},{name:'Demo_Portal_001',display:'Demo-Portal',position:[-450,700,12]}]}];else if(op==='ui_tree')return[{id:clients[0].id,tree:'WorldView\n  NPCRangeWin\n    titleText\n    interactButton\n  wndDialogMain\n    advanceDialogButton'}];else if(op==='cards')return[{id:clients[0].id,cards:[{name:'LifeBlade',display:'Lebensklinge',castable:true},{name:'ForestLord',display:'Waldfürst',castable:true},{name:'Rebirth',display:'Wiedergeburt',castable:false}]}];else if(op==='entity_tp')clients.forEach(c=>c.position=[600,980,12]);else if(op==='run_script'){const program=compileBot(args.source,libraryMap(),parseFlat);for(const step of botNodes(program))if(step.target&&!['mass','any'].includes(step.target)&&Number(step.target.slice(1))>args.ids.length)throw Error(`Zeile ${step.line}: Ziel fehlt in der Auswahl.`);runner=new AbortController();state.running=true;render();runDemo(program,args.ids,runner.signal);return{started:true};}else if(!['cast','pass','freecam','click_window'].includes(op))throw Error('Unbekannte Demo-Aktion.');render();return{ok:true,demo:true};}
 const delay=(ms,signal)=>new Promise((resolve,reject)=>{if(signal.aborted){reject(Error('Gestoppt'));return;}const done=()=>{signal.removeEventListener('abort',abort);resolve();};const timer=setTimeout(done,ms);function abort(){clearTimeout(timer);reject(Error('Gestoppt'));}signal.addEventListener('abort',abort,{once:true});});
 async function runDemo(program,selected,signal){try{const target=s=>s==='mass'||s==='any'?selected:[selected[Number(s.slice(1))-1]];await interpretBot(program,async s=>{if(s.op==='sleep'){await delay(s.seconds*1000,signal);return;}const rows=demoSelected(target(s.target));if(s.op==='teleport')rows.forEach(c=>c.position=[...s.xyz]);if(['quest_tp','navmap_tp'].includes(s.op))rows.forEach(c=>c.position=[500,800,12]);if(['entity_tp','nearest_entity','camera_tp','closest_mob'].includes(s.op))rows.forEach(c=>c.position=[600,980,12]);if(s.op==='key'&&s.key==='W')rows.forEach(c=>c.position[1]+=s.seconds*580);await delay(100,signal);render();},async c=>{const value=c.test==='incombat'?demoSelected(target(c.target)).some(r=>r.battle):false;return c.not?!value:value;},async(s,i)=>{$('script-progress').textContent=`DEMO · Schritt ${i} · Zeile ${s.line}`;},()=>delay(10,signal));log('DEMO · Bot abgeschlossen.');}catch(e){log('DEMO · Bot gestoppt: '+e.message,'warning');}finally{state.running=false;runner=null;$('script-progress').textContent='Demo-Bot beendet.';render();}}
