 settings=createMythicSettings({connected:()=>state.connected,command,toast,log,download,applyUi:value=>{uiPrefs=value;state.logs=state.logs.slice(-value.log_limit);renderLogs();},context:()=>({ids:ids(),source:$('script-editor').value,leader:$('movement-leader').value||null}),shortcut:async actionName=>{if(['sync','freecam','camera_tp','quest_tp','quest_all','speed_toggle','interact','combat_toggle','dialogue_toggle','questing_toggle','sigil_toggle'].includes(actionName)){await action('movement',{action:actionName,source:$('movement-leader').value||null});return;}const buttons={scan:'scan-button',hook:'hook-button',unhook:'unhook-button',run_script:'run-script',stop:'script-stop'};if(actionName==='forward'){await safe(()=>action('key',{ids:requireIds(),key:'W',seconds:settings.keySeconds()}))();}else{const button=$(buttons[actionName]);if(button.disabled){toast('Aktion derzeit nicht verfügbar. Verbindung, Auswahl und Skriptstatus prüfen.');return;}button.click();}}});;
 $('script-editor').addEventListener('input',()=>settings.context());
 tools=createMythicTools({action,toast,log,ids:requireIds,dialogue:()=>state.dialogue,automations:()=>state.automations,clients:()=>state.clients,available:()=>state.connected||state.demo,busy:()=>state.busy||state.running,esc,context:()=>settings.context(),importScript:(source,name)=>{currentScript=null;$('script-editor').value=source;$('script-name').value=name;renderScripts();settings.context();toast('Skript importiert. Vor Ausführung prüfen und speichern.');}});
 fishing=createFishing({state,command,toast,log});raids=createRaids({state,command,toast,log});studio=createScriptStudio({command,ids:requireIds,toast,esc});trace('app.init.ready');icons();renderScripts();renderWaypoints();render();navigate(location.hash.slice(1));log('Control Center bereit.');const pairWith=token=>{diag.secret(token);if(state.connected&&sessionPair.get()===token)return;sessionPair.set(token);const previous=state.socket;if(previous)previous.close();let attempts=0;const retry=()=>{if(state.socket){if(++attempts>60){trace('pairing.replace_timeout');toast('Vorherige Verbindung schließt nicht. Bridge neu starten.');return;}setTimeout(retry,100);return;}$('bridge-token').value=token;$('bridge-url').value='wss://localhost:18761/ws';$('connect-button').click();};retry();};
