 if(launchToken&&/^[A-Za-z0-9_-]{20,100}$/.test(launchToken)){const fresh=Boolean(handoff.get('pair'));(async()=>{if(fresh&&await tabs.offer(launchToken)){trace('browser.tab.reused');$('pairing-result').textContent='Vorhandenes Dashboard wird verwendet. Dieser Übergabe-Tab kann geschlossen werden.';window.close();return;}pairWith(launchToken);})().catch(e=>trace('browser.handoff.failed',{message:e.message}));}
